"use client";

import useSWR from "swr";

const fetcher = (url) => fetch(url).then((r) => r.json());

export default function ReelsSection({ region = "IN", category = "24" }) {
  const { data, error } = useSWR(
    `/api/youtube?region=${region}&category=${category}`,
    fetcher
  );

  if (error)
    return (
      <div className="p-4 bg-white rounded shadow">Error loading videos.</div>
    );
  if (!data)
    return <div className="p-4 bg-white rounded shadow">Loading reels…</div>;

  return (
    <div className="bg-white p-4 rounded shadow">
      <h2 className="font-bold text-lg mb-2">Entertainment Reels</h2>
      <ul className="space-y-4">
        {data.items.map((v) => (
          <li key={v.id} className="flex items-start gap-3">
            <img
              src={v.snippet.thumbnails.medium.url}
              alt=""
              className="w-20 h-12 object-cover rounded"
            />
            <div>
              <a
                href={`https://youtu.be/${v.id}`}
                target="_blank"
                rel="noopener noreferrer"
                className="font-medium hover:underline"
              >
                {v.snippet.title}
              </a>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
