"use client";

import Spline from "@splinetool/react-spline";
import { motion } from "framer-motion";

export default function Hero3D() {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
      className="bg-white rounded-lg shadow-lg overflow-hidden flex flex-col"
      style={{ height: "480px" }}
    >
      <div className="p-6">
        <h2 className="text-2xl font-bold mb-2">Welcome to Huddle</h2>
        <p className="text-gray-600 mb-4">
          Huddle is your one-stop community hub—chat, post, share and stay in
          the loop.
        </p>
      </div>
      <div className="flex-1 bg-gray-100">
        <Spline
          scene="https://prod.spline.design/ddfcede2-3431-45e5-bb8b-e2167e44ef07/scene.splinecode"
          style={{ width: "100%", height: "100%" }}
        />
      </div>
    </motion.div>
  );
}
